"""Phase 3 tables (docs/phase3_report_tables.md), generated from saved results only."""
import json
import numpy as np
from _common import RES, ROOT
from pcttd import ttdmetrics as TM

L = lambda p: json.loads((RES / p).read_text())
MJ = L("3d_mpb_analysis.json"); A3 = L("3a_mpb_designs.json")
DES = ("D0", "D1", "D2")
FJ = {d: L(f"3e_{d}_res30.json") for d in DES}
FZ = {d: np.load(RES / f"3e_{d}_res30.npz") for d in DES}
R40 = {d: (L(f"3e_{d}_res40.json"), np.load(RES / f"3e_{d}_res40.npz")) for d in DES if (RES / f"3e_{d}_res40.json").exists()}
GEO = {"D0": (1.0, 0.0), "D1": (1.2, -0.05), "D2": (1.2, -0.10)}
KEY = "tau_fit|validated|tol10"
o = []; w = o.append
pc = lambda x: f"{100*x:.1f}%"
w("# Phase 3 tables (generated by experiments/phase3/3g_tables.py from results/phase3/*.json)\n")
w("Units: a = c = 1, f = a/lambda; per-period delay tau_pp = n_g in a/c; GDD per period in (a/c)^2. FDTD columns are production runs "
  "(res 30, decay_tol = 1e-7, N = 4, 8, 12, plain-W1 leads, reference planes 3 periods outside the device). 'validated' = restricted to 0.231-0.268 (Phase 2 validation limit, upper edge chosen post hoc in Phase 2).\n")
w("## T1. Designs and run configuration\n")
c = FJ["D0"]["cfg"]
w("| design | f1 | s | r/a | N | res | decay_tol | d_src | d_mon | J (rows) | J_pml | wall time per run (min, N = 4/8/12) | max t_end |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|")
for d in DES:
    c = FJ[d]["cfg"]; ws = "/".join(f"{FJ[d]['wall_s'][str(N)]/60:.0f}" for N in FJ[d]["Ns"])
    w(f"| {d} | {GEO[d][0]} | {GEO[d][1]} | {c['r']} | {FJ[d]['Ns']} | {c['res']} | {c['decay_tol']:g} | {c['d_src']} | {c['d_mon']} | {c['J']} | {c['J_pml']} | {ws} | {max(FJ[d]['t_end'].values()):.0f} |")
w("\nLeads: plain W1 (f1 = 1, s = 0). Device section: rows |j| = 1 with radius f1 r, shifted by s (negative = toward the defect). Source: Hz line source shaped by the plain-W1 forward mode (f = 0.2475, fwidth 0.25).\n")
w("## T2. MPB (res 32, M = 6, nk = 101; Hz-even band 8)\n")
w("| design | band edge (min f) | band top | n_g,min (at f) | min gap to even band 7 / 9 | k-grid (51-pt spline vs HF) max rel. n_g diff, 0.231-0.268 | res 48 vs 32, max rel. n_g diff in MPB +-10% band | res 48 vs 32, worst over 0.231-0.268 (at f) |\n|---|---|---|---|---|---|---|---|")
for d in DES:
    m = MJ[d]
    r48 = f"{m['res48_vs_res32_ng_rel_in_mpb_tol10_validated_band']:.1e}" if "res48_vs_res32_ng_rel_in_mpb_tol10_validated_band" in m else "n/a (D0: converged in Phase 2)"
    w48 = f"{100*m['res48_vs_res32_ng_rel_validated']['maxabs']:.1f}% (at {m['res48_worst_f']:.3f})" if "res48_vs_res32_ng_rel_validated" in m else "n/a"
    w(f"| {d} | {m['band_edge_low']:.4f} | {m['band_top']:.4f} | {m['ng_min']:.2f} ({m['f_at_ng_min']:.4f}) | {m['min_gap_to_band7']:.4f} / {m['min_gap_to_band9']:.4f} | {m['kgrid51_spline_vs_HF_ng_maxrel_validated']:.1e} | {r48} | {w48} |")
w("\nBand identity of D1/D2: the engineered geometry is a continuous deformation of the plain W1 (same hole rows, only the rows |j| = 1 are modified); band 8 of the Hz-even class "
  "stays monotone decreasing over the retained branch and isolated from band 9 only narrowly (gap above); the identity was also confirmed by the FDTD: the measured Bloch phase per period tracks the MPB kappa of the same band (3-length fit rms <= 0.01 rad in the usable bands) and the FDTD transmission turns on at the MPB band edge. "
  "Confinement (strip energy) diagnostics were computed only for the plain W1 (Phase 2) and for R, not for D1/D2.\n")
w("## T3. Primary comparison: usable band (+-10% delay flatness, T >= 0.5 for N = 4, 8, 12), validated range 0.231-0.268\n")
w("| design | f1 | s | f_low | f_high | fractional BW | median tau_pp = n_g | ripple (max-min)/median | GDD at center (band-avg lin. fit / local-quad) | max abs GDD (local-quad, noise-limited) | T_min | R_max | projection residual median / max | max unitarity defect | GBP (BW x n_g) | periods for 25 carrier cycles | wavelengths (L f_c) | status |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|")
status = {"D0": "reference; band limited at the low end by the validated range edge and at the top by 0.268",
          "D1": "usable; narrower; band limited at the top by the validated-range edge 0.268",
          "D2": "usable; narrowest; band limited at the top by the validated-range edge 0.268"}
for d in DES:
    b = FJ[d]["bands"][KEY]
    w(f"| {d} | {GEO[d][0]} | {GEO[d][1]} | {b['f_low']:.4f} | {b['f_high']:.4f} | {pc(b['frac_bw'])} | {b['median_tau']:.3f} | {pc(b['ripple'])} | {b['gdd_band_avg_linfit']:.2f} / {b['gdd_center']:.2f} | {b['gdd_absmax']:.1f} | {b['T_min']:.3f} | {b['R_max']:.4f} | {b['res_median']:.3f} / {max(b['res_max'], b['res_max_out']):.3f} | {b['unitarity_defect_absmax']:.3f} | {b['gbp']:.3f} | {b['L_periods']:.1f} | {b['L_wavelengths']:.2f} | {status[d]} |")
w("\nGBP = fractional bandwidth x median n_g (declared definition). Target delay = 25 carrier cycles at the band center (criteria Revision 3). Band ends are limited by the 0.268 validated-range edge, so these are lower bounds of what the same rule gives without the restriction (T4).\n")
w("## T4. Sensitivity of the usable band: tolerance and domain restriction (FDTD, tau from the 3-length fit, central difference)\n")
w("| design | domain | +-5%: band (BW) | +-10% (primary): band (BW) | +-25%: band (BW) |\n|---|---|---|---|---|")
for d in DES:
    for lab, nm in (("validated", "0.231-0.268 (validated)"), ("full_0p22_0p275", "0.22-0.275 (NOT validated above 0.268)")):
        cells = []
        for tol in (5, 10, 25):
            b = FJ[d]["bands"][f"tau_fit|{lab}|tol{tol}"]
            cells.append(f"{b['f_low']:.4f}-{b['f_high']:.4f} ({pc(b['frac_bw'])}, n_g {b['median_tau']:.2f})" if b else "none")
        w(f"| {d} | {nm} | " + " | ".join(cells) + " |")
w("\nSame rule with the local-quadratic delay estimator (sensitivity only):\n")
w("| design | domain | +-5% | +-10% | +-25% |\n|---|---|---|---|---|")
for d in DES:
    for lab, nm in (("validated", "validated"), ("full_0p22_0p275", "0.22-0.275")):
        cells = []
        for tol in (5, 10, 25):
            b = FJ[d]["bands"][f"tau_fit_poly|{lab}|tol{tol}"]
            cells.append(f"{b['f_low']:.4f}-{b['f_high']:.4f} ({pc(b['frac_bw'])})" if b else "none")
        w(f"| {d} | {nm} | " + " | ".join(cells) + " |")
w("\n## T5. Stability of the delay across device length (inside each design's primary usable band)\n")
w("Median tau_pp over the band from each length pair (wave-cascade = exact, independent of interfaces and multiple reflections; 'S21 phase' = plain S21 phase difference, includes interface/Fabry-Perot phase) and the 3-length fit:\n")
w("| design | fit (4,8,12) | cascade 4-8 | cascade 8-12 | cascade 4-12 | S21 phase 4-8 | S21 phase 8-12 | S21 phase 4-12 | max abs rel. dev. of cascade vs fit (4-8 / 8-12 / 4-12) | FDTD vs MPB n_g: median / max abs |\n|---|---|---|---|---|---|---|---|---|---|")
for d in DES:
    b = FJ[d]["bands"][KEY]; sl = slice(b["i_low"], b["i_high"] + 1); z = FZ[d]
    med = lambda k: float(np.median(z[k][sl]))
    cv = b["cascade_vs_fit_rel_maxabs"]
    w(f"| {d} | {med('tau_fit'):.3f} | {med('tau_cas_4_8'):.3f} | {med('tau_cas_8_12'):.3f} | {med('tau_cas_4_12'):.3f} | {med('tau_s21_4_8'):.3f} | {med('tau_s21_8_12'):.3f} | {med('tau_s21_4_12'):.3f} | {pc(cv['4_8'])} / {pc(cv['8_12'])} / {pc(cv['4_12'])} | {100*b['tau_vs_mpb_rel_median']:+.1f}% / {pc(b['tau_vs_mpb_rel_maxabs'])} |")
w("\n## T6. Transmission, reflection, diagnostics inside the primary usable band, per length\n")
w("| design | N | T range | R max | |1-R-T| max | projection residual in/out max | 3-length fit rms max [rad] | t_end |\n|---|---|---|---|---|---|---|---|")
for d in DES:
    b = FJ[d]["bands"][KEY]; sl = slice(b["i_low"], b["i_high"] + 1); z = FZ[d]
    for N in FJ[d]["Ns"]:
        w(f"| {d} | {N} | {z[f'T_N{N}'][sl].min():.3f}-{z[f'T_N{N}'][sl].max():.3f} | {z[f'R_N{N}'][sl].max():.4f} | {np.abs(z[f'defect_N{N}'][sl]).max():.3f} | {z[f'res_in_N{N}'][sl].max():.3f} / {z[f'res_out_N{N}'][sl].max():.3f} | {z['fit_rms'][sl].max():.4f} | {FJ[d]['t_end'][str(N)]:.0f} |")
w("\nOutside the bands: |S21|^2 + |S11|^2 deviations and T > 1 are largest at the low-frequency end of the D0 analysis range (T up to "
  f"{max(FZ['D0'][f'T_N{N}'].max() for N in FJ['D0']['Ns']):.3f} for D0 at f < 0.23) and in the evanescent region of D1/D2 (below their band edges the device reflects: R -> 1).\n")
w("## T7. Production-resolution confirmation (res 40 vs res 30), validated range, +-10% rule\n")
if R40:
    w("| design | band res 30 | band res 40 | median n_g res 30 / 40 | ripple res 30 / 40 | max abs rel. diff of tau_fit (res 40 vs 30) inside the res-30 band | median rel. diff | T_min res 40 | R_max res 40 | max t_end res 40 | decay_tol |\n|---|---|---|---|---|---|---|---|---|---|---|")
    for d, (j4, z4) in R40.items():
        b3 = FJ[d]["bands"][KEY]; b4 = j4["bands"][KEY]; sl = slice(b3["i_low"], b3["i_high"] + 1)
        rd = z4["tau_fit"][sl] / FZ[d]["tau_fit"][sl] - 1
        w(f"| {d} | {b3['f_low']:.4f}-{b3['f_high']:.4f} ({pc(b3['frac_bw'])}) | {b4['f_low']:.4f}-{b4['f_high']:.4f} ({pc(b4['frac_bw'])}) | {b3['median_tau']:.3f} / {b4['median_tau']:.3f} | {pc(b3['ripple'])} / {pc(b4['ripple'])} | {pc(np.max(np.abs(rd)))} | {100*np.median(rd):+.2f}% | {b4['T_min']:.3f} | {b4['R_max']:.4f} | {max(j4['t_end'].values()):.0f} | {j4['cfg']['decay_tol']:g} |")
else:
    w("(res 40 runs not available)")
w("\n## T8. MPB-only n_g flatness bands (no transmission information), validated range and unrestricted\n")
w("| design | tolerance | domain | band | fractional BW | median n_g | ripple | GDD at center | max abs GDD | GBP | periods for 25 cycles |\n|---|---|---|---|---|---|---|---|---|---|---|")
for d in DES:
    for tol in (5, 10, 25):
        for lab, nm in (("validated", "0.231-0.268"), ("full", "analysis range 0.22-0.275")):
            b = MJ[d]["bands"][f"tol{tol}_{lab}"]
            if b:
                w(f"| {d} | +-{tol}% | {nm} | {b['f_low']:.4f}-{b['f_high']:.4f} | {pc(b['frac_bw'])} | {b['median_tau']:.2f} | {pc(b['ripple'])} | {b['gdd_center']:.2f} | {b['gdd_absmax']:.2f} | {b['gbp']:.3f} | {b['L_periods']:.1f} |")
w("\n## T9. Conventional R reference (square lattice, TM, r/a = 0.19 rods, one rod row removed): MPB ONLY - incomplete reference comparison\n")
R = MJ["R"]
w(f"Band: single guided band (MPB, res 24, nk = 61, M = 6), frequency range {R['f_range'][0]:.4f}-{R['f_range'][1]:.4f}; edge-row energy fraction max {R['edge_energy_max']:.1e}; strip-energy fraction min {R['strip_energy_min']:.2f}; n_g,min = {R['ng_min']:.2f}.\n")
w("| tolerance | band | fractional BW | median n_g | ripple | GDD at center | max abs GDD | GBP | periods (a_R) for 25 carrier cycles | wavelengths |\n|---|---|---|---|---|---|---|---|---|---|")
for tol in (5, 10, 25):
    b = R["bands"][f"tol{tol}_full"]
    w(f"| +-{tol}% | {b['f_low']:.4f}-{b['f_high']:.4f} | {pc(b['frac_bw'])} | {b['median_tau']:.2f} | {pc(b['ripple'])} | {b['gdd_center']:.2f} | {b['gdd_absmax']:.2f} | {b['gbp']:.3f} | {b['L_periods']:.1f} | {b['L_wavelengths']:.2f} |")
w("\nR carries no FDTD validation, no interface/transmission information and a coarser MPB (res 24, nk 61). Its retained branch was cut at f < 0.42 by the 3a band selection "
  "(its single-mode gap extends to ~0.43), so the +-10% band touches the retained upper limit (0.4193) and R's fractional bandwidths here are lower bounds, not converged band widths. "
  "Compare with the MPB rows of T8 for D0-D2, not with the FDTD rows.")
open(ROOT / "docs" / "phase3_report_tables.md", "w").write("\n".join(o) + "\n")
print("written docs/phase3_report_tables.md")
